mapper.insert:

    SELECT
    fn_get_dynamic_seq('utb_login_history') AS loginHistorySeq


INSERT INTO utb_login_history (
        user_mst_seq
      , office_seq
      , login_history_seq
      , login_ip
      , category
      , login_success_yn
      , login_device_type
      , login_country
      , login_type
      , create_user
      , create_at
      , del_yn
      , note
) VALUES (
       #{userMstSeq}
     , #{officeSeq}
     , #{loginHistorySeq}
     , NULLIF(#{loginIp}, '')::inet
     , #{category}
     , #{loginSuccessYn}
     , #{loginDeviceType}
     , #{loginCountry}
     , #{loginType}
     , #{createUser}
     , CURRENT_TIMESTAMP
     , 'N'
     , #{note}
         )
